def poly(xs: list, x: float) -> float:
    result = 0.0
    for coeff in reversed(xs):
        result = result * x + coeff
    return result


def _sign(x: float) -> int:
    return (x > 0) - (x < 0)


def find_zero(xs: list) -> float:
    lo, hi = -1.0, 1.0

    while _sign(poly(xs, lo)) == _sign(poly(xs, hi)) and _sign(poly(xs, lo)) != 0:
        lo *= 2.0
        hi *= 2.0

    while hi - lo > 1e-12:
        mid = (lo + hi) / 2.0
        if poly(xs, mid) == 0.0:
            return mid
        if _sign(poly(xs, lo)) * _sign(poly(xs, mid)) > 0:
            lo = mid
        else:
            hi = mid

    return (lo + hi) / 2.0
