def fizz_buzz(n: int) -> int:
    if n <= 0:
        return 0

    s = str(n - 1)
    dp = {(True, 0, 0): (1, 0)}

    for ch in s:
        limit = int(ch)
        ndp = {}

        for (tight, m11, m13), (cnt, sevens) in dp.items():
            max_d = limit if tight else 9

            for d in range(max_d + 1):
                ntight = tight and d == limit
                nm11 = (m11 * 10 + d) % 11
                nm13 = (m13 * 10 + d) % 13
                key = (ntight, nm11, nm13)

                old_cnt, old_sevens = ndp.get(key, (0, 0))
                ndp[key] = (
                    old_cnt + cnt,
                    old_sevens + sevens + (cnt if d == 7 else 0)
                )

        dp = ndp

    total = 0
    for (tight, m11, m13), (cnt, sevens) in dp.items():
        if m11 == 0 or m13 == 0:
            total += sevens

    return total
