def find_zero(xs: list):
    def poly(x):
        res = 0.0
        for c in reversed(xs):
            res = res * x + c
        return res

    def bisect(f, a, b):
        fa = f(a)
        fb = f(b)
        if fa == 0:
            return a
        if fb == 0:
            return b
        for _ in range(200):
            mid = a + (b - a) / 2.0
            fm = f(mid)
            if fm == 0:
                return mid
            if (fa < 0) != (fm < 0):
                b = mid
                fb = fm
            else:
                a = mid
                fa = fm
        return a + (b - a) / 2.0

    f0 = poly(0.0)
    if f0 == 0.0:
        return 0.0

    leading = None
    for c in reversed(xs):
        if c != 0:
            leading = c
            break

    sign_inf_pos = 1 if leading > 0 else -1

    if f0 > 0:
        direction = 1 if sign_inf_pos < 0 else -1
    else:
        direction = 1 if sign_inf_pos > 0 else -1

    step = 1.0
    x_prev = 0.0
    f_prev = f0
    x = direction * step
    f_x = poly(x)

    while True:
        if f_x == 0.0:
            return x
        if (f_prev > 0) != (f_x > 0):
            break
        x_prev = x
        f_prev = f_x
        step *= 2.0
        x = direction * step
        f_x = poly(x)

    return bisect(poly, x_prev, x)
