def prime_fib(n: int) -> int:
    import math

    def is_prime(x: int) -> bool:
        if x < 2:
            return False
        if x % 2 == 0:
            return x == 2
        limit = math.isqrt(x)
        for d in range(3, limit + 1, 2):
            if x % d == 0:
                return False
        return True

    a, b = 0, 1
    count = 0
    while True:
        a, b = b, a + b
        if is_prime(a):
            count += 1
            if count == n:
                return a
