def fibfib(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")
    if n < 2:
        return 0
    if n == 2:
        return 1

    def mat_mul(A, B):
        return [
            [
                A[i][0] * B[0][j] + A[i][1] * B[1][j] + A[i][2] * B[2][j]
                for j in range(3)
            ]
            for i in range(3)
        ]

    def mat_pow(mat, exp):
        result = [[1, 0, 0], [0, 1, 0], [0, 0, 1]]
        base = mat
        while exp > 0:
            if exp & 1:
                result = mat_mul(result, base)
            base = mat_mul(base, base)
            exp >>= 1
        return result

    M = [[1, 1, 1], [1, 0, 0], [0, 1, 0]]
    P = mat_pow(M, n - 2)
    return P[0][0]
