import re

def valid_date(date):
    if not date:
        return False
    try:
        if not re.fullmatch(r'\d{2}-\d{2}-\d{4}', date):
            return False
        month, day, year = map(int, date.split('-'))
        if month < 1 or month > 12:
            return False
        if day < 1:
            return False
        if month in [1, 3, 5, 7, 8, 10, 12]:
            return day <= 31
        if month in [4, 6, 9, 11]:
            return day <= 30
        if month == 2:
            return day <= 29
        return False
    except (ValueError, TypeError):
        return False
