def minPath(grid, k):
    n = len(grid)
    # Find the cell containing 1
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                r, c = i, j
                break
        else:
            continue
        break

    # Find the minimum value among the neighbors of 1
    min_neighbor = float('inf')
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < n and 0 <= nc < n:
            if grid[nr][nc] < min_neighbor:
                min_neighbor = grid[nr][nc]

    # Build the alternating path
    ans = []
    for i in range(k):
        if i % 2 == 0:
            ans.append(1)
        else:
            ans.append(min_neighbor)
    return ans
