def minPath(grid, k):
    n = len(grid)

    # Find the cell containing 1
    start_r = start_c = -1
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 1:
                start_r, start_c = r, c
                break
        if start_r != -1:
            break

    if k == 1:
        return [1]

    # Find the smallest neighbor of 1
    min_neighbor = float('inf')
    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        nr, nc = start_r + dr, start_c + dc
        if 0 <= nr < n and 0 <= nc < n:
            if grid[nr][nc] < min_neighbor:
                min_neighbor = grid[nr][nc]

    # The optimal path alternates between 1 and its smallest neighbor
    result = [1] * k
    for i in range(1, k, 2):
        result[i] = min_neighbor

    return result
