from decimal import Decimal

def _to_decimal(value):
    if isinstance(value, str):
        s = value.strip()
        if ',' in s and '.' in s:
            if s.rfind(',') > s.rfind('.'):
                s = s.replace('.', '').replace(',', '.')
            else:
                s = s.replace(',', '')
        else:
            s = s.replace(',', '.')
        return Decimal(s)
    return Decimal(str(value))

def compare_one(a, b):
    da = _to_decimal(a)
    db = _to_decimal(b)
    if da == db:
        return None
    return a if da > db else b
