def file_name_check(file_name):
    parts = file_name.split('.')
    if len(parts) != 2:
        return 'No'

    name, extension = parts

    if not name:
        return 'No'

    first_char = name[0]
    if not (('a' <= first_char <= 'z') or ('A' <= first_char <= 'Z')):
        return 'No'

    if extension not in ('txt', 'exe', 'dll'):
        return 'No'

    digit_count = sum(1 for ch in file_name if '0' <= ch <= '9')
    if digit_count > 3:
        return 'No'

    return 'Yes'
