    strongest_strength = (
        sum(1 for ch in strongest if ch.isalpha() and ch.isupper())
        - sum(1 for ch in strongest if ch.isalpha() and ch.islower())
    )

    for extension in extensions[1:]:
        strength = (
            sum(1 for ch in extension if ch.isalpha() and ch.isupper())
            - sum(1 for ch in extension if ch.isalpha() and ch.islower())
        )
        if strength > strongest_strength:
            strongest = extension
            strongest_strength = strength

    return f"{class_name}.{strongest}"

