def right_angle_triangle(a, b, c):
    if a <= 0 or b <= 0 or c <= 0:
        return False
    x, y, z = sorted((a, b, c))
    return z * z == x * x + y * y

def right_angle_triangle(a, b, c):
    x, y, z = sorted((a, b, c))
    return x > 0 and x * x + y * y == z * z

