def do_algebra(operator, operand):
    def apply(op, left, right):
        if op == '+':
            return left + right
        if op == '-':
            return left - right
        if op == '*':
            return left * right
        if op == '//':
            return left // right
        if op == '**':
            return left ** right
        raise ValueError(f"Unsupported operator: {op}")

    precedence = {'+': 1, '-': 1, '*': 2, '//': 2, '**': 3}
    values = [operand[0]]
    ops = []

    for op, num in zip(operator, operand[1:]):
        while ops and (
            precedence[ops[-1]] > precedence[op]
            or (precedence[ops[-1]] == precedence[op] and op != '**')
        ):
            right = values.pop()
            left = values.pop()
            values.append(apply(ops.pop(), left, right))
        ops.append(op)
        values.append(num)

    while ops:
        right = values.pop()
        left = values.pop()
        values.append(apply(ops.pop(), left, right))

    return values[0]
